    svg_code = 'function generateArtisanSvg(item) {\n        const cols = (item.color || \'6366f1,a855f7\').split(\',\');\n        const c1 = \'#\' + (cols[0] || \'6366f1\');\n        const c2 = \'#\' + (cols[1] || \'a855f7\');\n        const id = \'svg-grad-\' + item.id;\n        const name = String(item.name).replace(/[<&>]/g, \'\');\n        const lower = String(item.name).toLowerCase();\n\n        if (lower.includes(\'neobrutalism\') || lower.includes(\'brutalism\')) {\n            return `data:image/svg+xml;utf8,` + encodeURIComponent(`\n            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 240" style="background:#FDE047;">\n                <rect x="0" y="0" width="400" height="240" fill="#FACC15"/>\n                <rect x="34" y="34" width="340" height="170" fill="#000000"/>\n                <rect x="30" y="30" width="340" height="170" fill="#FFFFFF" stroke="#000000" stroke-width="4"/>\n                <rect x="50" y="50" width="80" height="28" fill="#EC4899" stroke="#000000" stroke-width="3"/>\n                <rect x="140" y="50" width="120" height="28" fill="#3B82F6" stroke="#000000" stroke-width="3"/>\n                <circle cx="330" cy="64" r="14" fill="#10B981" stroke="#000000" stroke-width="3"/>\n                <rect x="50" y="95" width="290" height="40" fill="#F8FAFC" stroke="#000000" stroke-width="3"/>\n                <rect x="65" y="107" width="140" height="16" fill="#000000"/>\n                <rect x="50" y="150" width="100" height="32" fill="#000000"/>\n                <rect x="46" y="146" width="100" height="32" fill="#A855F7" stroke="#000000" stroke-width="3"/>\n                <text x="96" y="167" font-family="\'Arial Black\', sans-serif" font-size="12" font-weight="900" fill="#000" text-anchor="middle">SUBMIT ❯</text>\n                <text x="200" y="222" font-family="\'Arial Black\', sans-serif" font-size="14" font-weight="900" fill="#000" text-anchor="middle">${name.toUpperCase()}</text>\n            </svg>`);\n        }\n\n        if (lower.includes(\'frutiger\') || lower.includes(\'aero\')) {\n            return `data:image/svg+xml;utf8,` + encodeURIComponent(`\n            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 240">\n                <defs>\n                    <linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1">\n                        <stop offset="0%" stop-color="#38BDF8"/>\n                        <stop offset="60%" stop-color="#E0F2FE"/>\n                        <stop offset="100%" stop-color="#22C55E"/>\n                    </linearGradient>\n                    <radialGradient id="bubble" cx="35%" cy="35%" r="65%">\n                        <stop offset="0%" stop-color="#ffffff" stop-opacity="0.9"/>\n                        <stop offset="50%" stop-color="#38BDF8" stop-opacity="0.4"/>\n                        <stop offset="100%" stop-color="#0284C7" stop-opacity="0.8"/>\n                    </radialGradient>\n                </defs>\n                <rect width="400" height="240" fill="url(#${id})"/>\n                <circle cx="320" cy="70" r="45" fill="url(#bubble)"/>\n                <ellipse cx="310" cy="55" rx="18" ry="10" fill="#ffffff" opacity="0.6"/>\n                <circle cx="100" cy="140" r="30" fill="url(#bubble)"/>\n                <rect x="60" y="45" width="280" height="135" rx="16" fill="rgba(255,255,255,0.4)" stroke="#ffffff" stroke-width="2"/>\n                <rect x="60" y="45" width="280" height="34" rx="16" fill="rgba(255,255,255,0.6)"/>\n                <circle cx="80" cy="62" r="6" fill="#EF4444"/>\n                <circle cx="98" cy="62" r="6" fill="#F59E0B"/>\n                <circle cx="116" cy="62" r="6" fill="#10B981"/>\n                <rect x="80" y="95" width="130" height="26" rx="13" fill="url(#bubble)" stroke="#ffffff" stroke-width="1.5"/>\n                <text x="200" y="222" font-family="\'Segoe UI\', sans-serif" font-size="14" font-weight="bold" fill="#0369A1" text-anchor="middle">${name}</text>\n            </svg>`);\n        }\n\n        if (lower.includes(\'cyberpunk\') || lower.includes(\'terminal\') || lower.includes(\'matrix\') || lower.includes(\'sci-fi\')) {\n            return `data:image/svg+xml;utf8,` + encodeURIComponent(`\n            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 240" style="background:#050508;">\n                <defs>\n                    <pattern id="grid" width="20" height="20" patternUnits="userSpaceOnUse">\n                        <path d="M 20 0 L 0 0 0 20" fill="none" stroke="rgba(6,182,212,0.15)" stroke-width="1"/>\n                    </pattern>\n                </defs>\n                <rect width="400" height="240" fill="url(#grid)"/>\n                <circle cx="200" cy="100" r="65" fill="none" stroke="${c2}" stroke-width="1.5" stroke-dasharray="8 4" opacity="0.8"/>\n                <circle cx="200" cy="100" r="45" fill="none" stroke="#22D3EE" stroke-width="1"/>\n                <rect x="40" y="35" width="110" height="40" fill="rgba(5,5,8,0.8)" stroke="#EC4899" stroke-width="1.5"/>\n                <text x="50" y="58" font-family="\'JetBrains Mono\', monospace" font-size="10" fill="#EC4899">&gt; SYS_OK: 99%</text>\n                <rect x="250" y="35" width="110" height="40" fill="rgba(5,5,8,0.8)" stroke="#22D3EE" stroke-width="1.5"/>\n                <text x="260" y="58" font-family="\'JetBrains Mono\', monospace" font-size="10" fill="#22D3EE">&gt; CORE_ONLINE</text>\n                <rect x="120" y="145" width="160" height="30" fill="#000000" stroke="${c2}" stroke-width="1"/>\n                <rect x="125" y="152" width="90" height="16" fill="${c2}"/>\n                <text x="200" y="222" font-family="\'JetBrains Mono\', monospace" font-size="13" font-weight="bold" fill="#22D3EE" text-anchor="middle">${name.toUpperCase()}</text>\n            </svg>`);\n        }\n\n        if (lower.includes(\'bento\')) {\n            return `data:image/svg+xml;utf8,` + encodeURIComponent(`\n            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 240" style="background:#0F1420;">\n                <rect x="30" y="25" width="160" height="95" rx="14" fill="#182235" stroke="#2D3748" stroke-width="1.5"/>\n                <circle cx="55" cy="50" r="12" fill="#6366F1"/>\n                <rect x="75" y="44" width="80" height="12" rx="4" fill="#CBD5E1"/>\n                <rect x="50" y="75" width="120" height="24" rx="6" fill="#202D45"/>\n                <rect x="202" y="25" width="168" height="60" rx="14" fill="#182235" stroke="#2D3748" stroke-width="1.5"/>\n                <text x="220" y="52" font-family="sans-serif" font-size="18" font-weight="bold" fill="#38BDF8">84.5%</text>\n                <text x="220" y="68" font-family="sans-serif" font-size="9" fill="#94A3B8">Conversion Rate</text>\n                <rect x="202" y="95" width="168" height="90" rx="14" fill="#182235" stroke="#2D3748" stroke-width="1.5"/>\n                <rect x="218" y="115" width="40" height="50" rx="4" fill="#4F46E5"/>\n                <rect x="264" y="130" width="40" height="35" rx="4" fill="#818CF8"/>\n                <rect x="310" y="105" width="40" height="60" rx="4" fill="#A855F7"/>\n                <rect x="30" y="130" width="160" height="55" rx="14" fill="#182235" stroke="#2D3748" stroke-width="1.5"/>\n                <text x="50" y="162" font-family="sans-serif" font-size="14" font-weight="bold" fill="#10B981">+34.8% MoM</text>\n                <text x="200" y="222" font-family="sans-serif" font-size="13" font-weight="bold" fill="#E2E8FF" text-anchor="middle">${name}</text>\n            </svg>`);\n        }\n\n        if (lower.includes(\'bauhaus\')) {\n            return `data:image/svg+xml;utf8,` + encodeURIComponent(`\n            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 240" style="background:#F4F1EA;">\n                <circle cx="120" cy="90" r="55" fill="#DC2626"/>\n                <rect x="180" y="40" width="100" height="100" fill="#2563EB"/>\n                <polygon points="300,160 360,40 380,160" fill="#FACC15"/>\n                <line x1="20" y1="160" x2="380" y2="160" stroke="#000000" stroke-width="6"/>\n                <rect x="40" y="175" width="18" height="18" fill="#000000"/>\n                <text x="200" y="215" font-family="\'Helvetica\', Arial, sans-serif" font-size="15" font-weight="900" fill="#000" text-anchor="middle">${name.toUpperCase()}</text>\n            </svg>`);\n        }\n\n        // Generic Radiant Fallback\n        return `data:image/svg+xml;utf8,` + encodeURIComponent(`\n        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 240">\n            <defs>\n                <linearGradient id="${id}" x1="0" y1="0" x2="1" y2="1">\n                    <stop offset="0%" stop-color="${c1}"/>\n                    <stop offset="100%" stop-color="${c2}"/>\n                </linearGradient>\n            </defs>\n            <rect width="400" height="240" fill="#080C14"/>\n            <circle cx="280" cy="70" r="90" fill="url(#${id})" opacity="0.35" filter="blur(20px)"/>\n            <circle cx="100" cy="160" r="70" fill="${c1}" opacity="0.25" filter="blur(25px)"/>\n            <rect x="45" y="35" width="310" height="145" rx="16" fill="rgba(255,255,255,0.05)" stroke="rgba(255,255,255,0.15)" stroke-width="1.5"/>\n            <rect x="65" y="55" width="40" height="40" rx="10" fill="url(#${id})"/>\n            <rect x="120" y="60" width="140" height="12" rx="4" fill="#FFFFFF" opacity="0.9"/>\n            <rect x="120" y="80" width="90" height="8" rx="4" fill="#94A3B8" opacity="0.6"/>\n            <rect x="65" y="115" width="120" height="28" rx="8" fill="url(#${id})" opacity="0.9"/>\n            <rect x="195" y="115" width="80" height="28" rx="8" fill="rgba(255,255,255,0.1)" stroke="rgba(255,255,255,0.2)"/>\n            <text x="200" y="218" font-family="\'Inter\', sans-serif" font-size="13" font-weight="700" fill="#FFFFFF" text-anchor="middle">${name}</text>\n        </svg>`);\n    }'
    return mock_code, svg_code
